// A new creation (no id) or one of hers to edit. The kind list is the option set, in its order, in the reader's words.
const c = Inputs.creation && typeof Inputs.creation === 'object' ? Inputs.creation : {};
const get = (m, k) => (m && typeof m.get === 'function' ? m.get(k) : m && m[k]);
const words = {
  'creations.kindDocument': Inputs.kDocument, 'creations.kindInteractive': Inputs.kInteractive, 'creations.kindPrompt': Inputs.kPrompt,
  'creations.kindAudioVideo': Inputs.kAudioVideo, 'creations.kindLink': Inputs.kLink, 'creations.kindOther': Inputs.kOther
};
Outputs.kindItems = (Inputs.kinds || []).map((k) => ({ Label: words[get(k, 'labelKey')] || get(k, 'kind'), Value: get(k, 'kind') }));
const isNew = !c.id;
Outputs.id = c.id || '';
Outputs.isNew = isNew;
Outputs.headKey = isNew ? 'creations.addHead' : 'creations.editHead';
Outputs.title = c.title || '';
Outputs.kind = c.kind || 'document';
Outputs.madeWith = c.madeWith || '';
Outputs.description = c.description || '';
Outputs.usedInClass = c.usedInClass === true;
Outputs.form = isNew ? '' : String(c.form || '');
Outputs.fromHandIn = c.fromHandIn === true;
Outputs.url = !isNew && c.form === 'link' ? String(c.url || '') : '';
Outputs.text = !isNew && c.form === 'text' ? String(c.text || '') : '';
const files = Array.isArray(c.files) ? c.files : [];
Outputs.keptKey = isNew ? '' : c.fromHandIn === true ? 'creations.keptHandIn' : c.form === 'file' ? 'creations.keptFile' : '';
Outputs.keptName = files.length ? String(files[0].fileName || '') : '';
Outputs.showKept = !isNew && (c.fromHandIn === true || c.form === 'file');
Outputs.canDelete = !isNew;
Outputs.opened();
Outputs.toFile();

// New: the tabs, and the open tab's part. Editing: no tabs; her own link or text can be changed,
// a file or a hand-in cannot (what it keeps is said in a sentence instead).
const isNew = Inputs.isNew === true;
const own = Inputs.fromHandIn !== true;
Outputs.showTabs = isNew;
Outputs.showFile = isNew && Inputs.tabFile === true;
Outputs.showLink = isNew ? Inputs.tabLink === true : own && Inputs.form === 'link';
Outputs.showText = isNew ? Inputs.tabText === true : own && Inputs.form === 'text';
Outputs.showDelete = Inputs.canDelete === true && Inputs.confirming !== true;

// A link is a link and text is a prompt; a file is what its ending says (Option sets/Creation kinds).
// Only while adding: an existing creation keeps the kind she gave it. She can always change it.
if (Inputs.isNew !== true) return;
const tab = String(Inputs.tab || 'file');
Outputs.kind = tab === 'link' ? 'link' : tab === 'text' ? 'prompt' : String(Inputs.fileKind || 'document');

parameters.code:
/*
 * The one file a new creation keeps: a kind on the hand-in list (Option sets/Hand-in kinds), up to
 * 50 MB, judged from its name and size before anything is uploaded; saveCreation checks it again,
 * from its bytes. Choosing or dropping another replaces it. `kindGuess` is its creation kind, from
 * the endings Option sets/Creation kinds lists. `start` puts it on `current` for the Upload File
 * node; the node's done comes back as `uploaded`, and `stored` fires with its stored name.
 */
const MAX_BYTES = 50 * 1024 * 1024;
let chosen = null;

Script.Inputs = { kinds: 'array', creationKinds: 'array', picked: '*', pickedName: 'string', pickedSize: 'number', dropped: 'array', cloudFile: '*' };
Script.Outputs = {
  current: '*', hasFile: 'boolean', name: 'string', size: 'string', accept: 'string', kindGuess: 'string',
  whyKey: 'string', whyName: 'string', refused: 'signal', accepted: 'signal', uploadNow: 'signal', storedName: 'string', stored: 'signal'
};

const get = (m, k) => (m && typeof m.get === 'function' ? m.get(k) : m && m[k]);
const extOf = (n) => { const s = String(n || ''); const d = s.lastIndexOf('.'); return d > 0 ? s.slice(d + 1).toLowerCase() : ''; };
const exts = () => (Script.Inputs.kinds || []).map((k) => get(k, 'ext')).filter(Boolean);
const sizeText = (n) => (n >= 1024 * 1024 ? (n / (1024 * 1024)).toFixed(1) + ' MB' : Math.max(1, Math.round(n / 1024)) + ' KB');

function publish() {
  Script.Outputs.hasFile = !!chosen;
  Script.Outputs.name = chosen ? chosen.name : '';
  Script.Outputs.size = chosen ? sizeText(chosen.size) : '';
  const ext = chosen ? extOf(chosen.name) : '';
  const row = (Script.Inputs.creationKinds || []).find((k) => ext && String(get(k, 'exts') || '').split(',').includes(ext));
  Script.Outputs.kindGuess = row ? get(row, 'kind') : 'document';
}
function take(file, rawName, rawSize) {
  const name = String(rawName || '');
  const size = Number(rawSize) || 0;
  if (!file || !name) return;
  if (!exts().includes(extOf(name))) { Script.Outputs.whyKey = 'creations.badType'; Script.Outputs.whyName = name; Script.Outputs.refused(); return; }
  if (size > MAX_BYTES) { Script.Outputs.whyKey = 'creations.tooBig'; Script.Outputs.whyName = name; Script.Outputs.refused(); return; }
  chosen = { file, name, size };
  publish();
  Script.Outputs.accepted();
}

Script.OnInit = function () { publish(); };
Script.Setters.kinds = function () {
  Script.Outputs.accept = exts().map((e) => '.' + e).join(',');
};
Script.Signals.addPicked = function () { take(Script.Inputs.picked, Script.Inputs.pickedName, Script.Inputs.pickedSize); };
Script.Signals.addDropped = function () {
  const f = Array.from(Script.Inputs.dropped || [])[0];
  if (f) take(f, f.name, f.size);
};
Script.Signals.start = function () {
  if (!chosen) return;
  Script.Outputs.current = chosen.file;
  Script.Outputs.uploadNow();
};
Script.Signals.uploaded = function () {
  const f = Script.Inputs.cloudFile;
  Script.Outputs.storedName = f ? (typeof f.getName === 'function' ? f.getName() : String(f.name || '')) : '';
  Script.Outputs.stored();
};
Script.Signals.clear = function () {
  chosen = null;
  publish();
};

parameters.functionScript:
// Words first, then what it holds. A new file is uploaded before saveCreation is called; anything else goes straight there.
const refuse = (key) => { Outputs.whyKey = key; Outputs.refuse(); };
if (!String(Inputs.title || '').trim()) return refuse('creations.needTitle');
const isNew = Inputs.isNew === true;
const form = isNew ? String(Inputs.tab || 'file') : String(Inputs.form || '');
const own = isNew || Inputs.fromHandIn !== true;
if (isNew && form === 'file') {
  if (!Inputs.hasFile) return refuse('creations.needFile');
  Outputs.upload();
  return;
}
if (own && form === 'link' && !String(Inputs.url || '').trim()) return refuse('creations.needLink');
if (own && form === 'text' && !String(Inputs.text || '').trim()) return refuse('creations.needText');
Outputs.send();

// Runs once the file is uploaded (a new file) or straight from the check, and fires go in the same run.
const isNew = Inputs.isNew === true;
const form = isNew ? String(Inputs.tab || 'file') : String(Inputs.form || '');
Outputs.id = isNew ? '' : String(Inputs.id || '');
Outputs.form = form;
Outputs.file = isNew && form === 'file' ? String(Inputs.storedName || '') : '';
Outputs.url = form === 'link' ? String(Inputs.url || '') : '';
Outputs.text = form === 'text' ? String(Inputs.text || '') : '';
Outputs.go();
